svg.metadata:
# Simple 3-tier application: auth proxy at the edge, web / app / data tiers. # All user traffic passes the oauth2 proxy, which validates sessions against # an external IdP before anything reaches the web tier. diagram: title: 3-tier app + auth proxy direction: down
nodes: - id: users label: Users type: user - id: idp label: Identity Provider type: cloud - id: authproxy label: oauth2-proxy type: lb ip: 192.0.2.10 os: linux - id: web1 label: web-01 type: vm # web tier runs on VMs icon: web ip: 10.1.10.11 os: linux - id: web2 label: web-02 type: vm icon: web ip: 10.1.10.12 os: linux - id: app1 label: app-01 type: container ip: 10.1.20.11 os: linux - id: app2 label: app-02 type: container ip: 10.1.20.12 os: linux - id: db1 label: pg-primary type: metal # data tier on bare metal; icon keeps the db glyph icon: db ip: 10.1.30.11 os: linux - id: db2 label: pg-replica type: metal icon: db ip: 10.1.30.12 os: linux
groups: - id: edge label: Edge class: zone cidr: 192.0.2.0/24 nodes: [authproxy] - id: web label: Web tier class: subnet cidr: 10.1.10.0/24 nodes: [web1, web2] - id: app label: App tier class: subnet cidr: 10.1.20.0/24 nodes: [app1, app2] - id: data label: Data tier class: trust cidr: 10.1.30.0/24 nodes: [db1, db2] - id: ext label: Cloud — IdP class: cloud nodes: [idp]
connections: # edge labels follow "<proto>/<port> <context>" - {from: users, to: authproxy, label: "tcp/443 https", protocol: tcp, port: 443, comment: "all user traffic via the auth proxy"} - {from: authproxy, to: idp, label: "tcp/443 oidc", protocol: tcp, port: 443} - {from: authproxy, to: web1, label: "tcp/8443 https", protocol: tcp, port: 8443} - {from: authproxy, to: web2, label: "tcp/8443 https", protocol: tcp, port: 8443} - {from: web, to: app, label: "tcp/8080 api", protocol: tcp, port: 8080} - {from: app, to: db1, label: "tcp/5432 pgsql", protocol: tcp, port: 5432} - {from: db1, to: db2, label: "tcp/5432 repl", protocol: tcp, port: 5432, direction: both, comment: "streaming replication"}
# views: the auth path is the reviewable story here; the tiers are the rest views: - {id: auth, title: "3-tier — auth path", focus: authproxy, depth: 1} - {id: tiers, title: "3-tier — tier to tier", focus: app, depth: 1} - {id: data, title: "3-tier — data tier", focus: db1, depth: 1}
